* { box-sizing: border-box; margin: 0; padding: 0; }
[hidden] { display: none !important; }
body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 2rem 1rem;
}
.card {
  background: #16213e;
  border: 4px solid #0f3460;
  padding: 2rem;
  width: 100%;
  max-width: 500px;
  box-shadow: 8px 8px 0 #0f3460;
}
h1 {
  font-size: 1.75rem;
  margin-bottom: 1rem;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.counts {
  display: flex;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
  font-size: 1.1rem;
}
.counts strong {
  color: #e94560;
}
.input-row {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}
#todo-input {
  flex: 1;
  padding: 0.75rem;
  font-size: 1rem;
  border: 3px solid #0f3460;
  background: #1a1a2e;
  color: #e0e0e0;
  outline: none;
}
#todo-input:focus {
  border-color: #e94560;
}
#todo-add {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: bold;
  background: #e94560;
  color: #fff;
  border: 3px solid #e94560;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
}
#todo-add:hover {
  background: #ff6b81;
  border-color: #ff6b81;
}
#todo-add:active {
  transform: translate(2px, 2px);
}
#todo-add:focus-visible {
  outline: 3px solid #e0e0e0;
  outline-offset: 2px;
}
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.todo-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: #1a1a2e;
  padding: 0.75rem;
  border: 2px solid #0f3460;
}
.todo-item input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  cursor: pointer;
  accent-color: #e94560;
}
.todo-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}
.todo-item input:checked + .todo-text {
  text-decoration: line-through;
  opacity: 0.6;
}
.todo-delete {
  padding: 0.4rem 0.75rem;
  font-size: 0.9rem;
  background: transparent;
  color: #e94560;
  border: 2px solid #e94560;
  cursor: pointer;
  font-weight: bold;
}
.todo-delete:hover {
  background: #e94560;
  color: #fff;
}
.todo-delete:active {
  transform: translate(1px, 1px);
}
.todo-delete:focus-visible {
  outline: 3px solid #e0e0e0;
  outline-offset: 2px;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 1.25rem; }
  .input-row { flex-direction: column; }
  #todo-add { width: 100%; }
}

let nextId = 1;
let tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const list = document.getElementById('todo-list');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function renderTask(task) {
  const li = document.createElement('li');
  li.className = 'todo-item';
  li.dataset.id = task.id;

  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.id = 'todo-check-' + task.id;
  cb.checked = task.done;
  cb.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
  cb.addEventListener('change', () => {
    task.done = cb.checked;
    updateCounts();
  });

  const span = document.createElement('span');
  span.className = 'todo-text';
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'todo-delete';
  del.id = 'todo-delete-' + task.id;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', 'Delete task ' + task.id);
  del.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.appendChild(cb);
  li.appendChild(span);
  li.appendChild(del);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  renderTask(task);
  updateCounts();
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', (e) => {
  e.preventDefault();
  addTask();
});

input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask();
  }
});

updateCounts();
